<?php require_once 'config/database.php'; require_once 'config/auth.php'; if(current_user()){header('Location: '.BASE_URL.'/index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=strtolower(trim($_POST['email']??'')); $password=(string)($_POST['password']??''); $s=$pdo->prepare("SELECT * FROM users WHERE LOWER(email)=? AND is_active=1 LIMIT 1"); $s->execute([$email]); $u=$s->fetch(); if($u && password_verify($password,$u['password_hash'])){ $_SESSION['user']=$u; audit($pdo,'LOGIN','users',(int)$u['id'],'Login berhasil'); header('Location: '.BASE_URL.'/index.php'); exit; } $error='Email atau password tidak sesuai.'; }
